-- Original: server/internal/quest/upstream/projecteq/wakening/Eysa_Florawhisper.pl (sha256 1095c70c5293414b524cdbaa56898813e0830f18f3c24bc5453a84b448689120)
-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- P99 Emil route replaces the later Dolvak report/depop branch. Seed-bag faction is the documented +20; XP uses existing ProjectEQ magnitudes.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("A pleasure to meet you. I am Countess Eysa Florawhisper of the Tunarean Court. Are you a friend of the court?")
  elseif e.message:findi("friend of the court") then
    e.self:Say("You appear to be a creature that has seen many foreign lands. There are a number of fruits and seeds that I desire in order to plant them and preserve their species here in the wakening land. I will provide a bag for you that will preserve the seeds until they can be returned to me. Will you gather seeds for me? ")
  elseif e.message:findi("gather") then
    e.self:Say("I seek the following fruits and seeds. A misty acorn, emerald orange, bag of caynar nuts, vineclinger berries, ripened heartfruit, rathe berries, marr cherries, and flarefire seeds.")
    e.other:SummonItem(17864)
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 29067 }) then
    e.self:Say("Ahh, why thank you, friend! We are grateful. I believe if we work together, those children of Zek can be driven back in time. Otherwise, survival hangs in the balance, for both of us. Take this token back to the sentry as a symbol of our acceptance.")
    e.other:SummonItem(29623)
    e.other:Faction(449, 10, 0)
    e.other:AddEXP(5000)
  elseif item_lib.check_turn_in(e.trade, { item1 = 24863 }) then
    e.self:Say("Ohhhh! You're the sweetest, " .. e.other:GetCleanName() .. ". The nymphs of the Tunarean Court recognize you as a friend of our kind and our botanical brethren.")
    e.other:Faction(449, 20, 0)
    e.other:AddEXP(5000)
    e.other:SummonItem(24864)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
